"""Load mirt reference cases from tests/reference/*.json (generated by validation/r/*.R)."""

from __future__ import annotations

import json
from collections.abc import Mapping
from dataclasses import dataclass
from pathlib import Path
from typing import Any

import numpy as np
import pandas as pd

REFERENCE_DIR = Path(__file__).parent / "reference"


def check_reference_meta(
    meta: Mapping[str, Any],
    *,
    require_richardson: bool = False,
    require_grid_check: bool = False,
) -> None:
    """Assert that mirt reference metadata records converged fits and the requested grid."""
    case = meta.get("case", "<unknown>")
    assert meta.get("converged") is True, f"Reference {case!r}: Oakes fit did not converge."
    if require_richardson or "converged_richardson" in meta:
        assert meta.get("converged_richardson") is True, (
            f"Reference {case!r}: Richardson fit did not converge."
        )
    if require_grid_check or "grid_check" in meta:
        assert "grid_check" in meta and "theta_lim" in meta, (
            f"Reference {case!r}: missing grid_check or theta_lim in meta."
        )
        assert meta["grid_check"] == meta["theta_lim"], (
            f"Reference {case!r}: grid_check {meta['grid_check']!r} "
            f"!= theta_lim {meta['theta_lim']!r}."
        )


@dataclass(frozen=True)
class Case:
    name: str
    raw: dict[str, Any]

    @property
    def items(self) -> list[str]:
        return list(self.raw["items"])

    @property
    def itemtype(self) -> str:
        return str(self.raw["meta"]["itemtype"])

    @property
    def patterns(self) -> pd.DataFrame:
        return pd.DataFrame(np.asarray(self.raw["patterns"], dtype=int), columns=self.items)

    @property
    def data(self) -> pd.DataFrame:
        counts = np.asarray(self.raw["counts"], dtype=int)
        return pd.DataFrame(
            np.repeat(np.asarray(self.raw["patterns"], dtype=int), counts, axis=0),
            columns=self.items,
        )

    def params(self, key: str = "params") -> pd.DataFrame:
        src = self.raw[key] if key == "params" else self.raw[key]["params"]
        return pd.DataFrame(src).T.astype(float).loc[self.items]

    def latent(self, key: str = "latent") -> dict[str, float | None]:
        src = self.raw[key] if key == "latent" else self.raw[key]["latent"]
        return {k: (None if v is None else float(v)) for k, v in src.items()}


def load(name: str) -> Case:
    raw = dict(json.loads((REFERENCE_DIR / f"{name}.json").read_text()))
    check_reference_meta(raw["meta"])
    return Case(name, raw)
